1: # the name by which the project can be referenced within Serena
2: project_name: "workspace"
3: 
4: 
5: # list of languages for which language servers are started; choose from:
6: #   al                  angular             ansible             bash                clojure
7: #   cpp                 cpp_ccls            crystal             csharp              csharp_omnisharp
8: #   dart                elixir              elm                 erlang              fortran
9: #   fsharp              go                  groovy              haskell             haxe
10: #   hlsl                html                java                json                julia
11: #   kotlin              lean4               lua                 luau                markdown
12: #   matlab              msl                 nix                 ocaml               pascal
13: #   perl                php                 php_phpactor        powershell          python
14: #   python_jedi         python_ty           r                   rego                ruby
15: #   ruby_solargraph     rust                scala               scss                solidity
16: #   svelte              swift               systemverilog       terraform           toml
17: #   typescript          typescript_vts      vue                 yaml                zig
18: #   (This list may be outdated. For the current list, see values of Language enum here:
19: #   https://github.com/oraios/serena/blob/main/src/solidlsp/ls_config.py
20: #   For some languages, there are alternative language servers, e.g. csharp_omnisharp, ruby_solargraph.)
21: # Note:
22: #   - For C, use cpp
23: #   - For JavaScript, use typescript
24: #   - For Angular projects, use angular (subsumes typescript+html; requires `npm install` in the project root)
25: #   - For Svelte projects, use svelte (subsumes typescript/javascript for .svelte projects; requires npm)
26: #   - For SCSS / Sass / plain CSS, use scss (some-sass-language-server handles all three)
27: #   - For Free Pascal/Lazarus, use pascal
28: # Special requirements:
29: #   Some languages require additional setup/installations.
30: #   See here for details: https://oraios.github.io/serena/01-about/020_programming-languages.html#language-servers
31: # When using multiple languages, the first language server that supports a given file will be used for that file.
32: # The first language is the default language and the respective language server will be used as a fallback.
33: # Note that when using the JetBrains backend, language servers are not used and this list is correspondingly ignored.
34: languages:
35: - typescript
36: 
37: # the encoding used by text files in the project
38: # For a list of possible encodings, see https://docs.python.org/3.11/library/codecs.html#standard-encodings
39: encoding: "utf-8"
40: 
41: # line ending convention to use when writing source files.
42: # Possible values: unset (use global setting), "lf", "crlf", or "native" (platform default)
43: # This does not affect Serena's own files (e.g. memories and configuration files), which always use native line endings.
44: line_ending:
45: 
46: # The language backend to use for this project.
47: # If not set, the global setting from serena_config.yml is used.
48: # Valid values: LSP, JetBrains
49: # Note: the backend is fixed at startup. If a project with a different backend
50: # is activated post-init, an error will be returned.
51: language_backend:
52: 
53: # whether to use project's .gitignore files to ignore files
54: ignore_all_files_in_gitignore: true
55: 
56: # advanced configuration option allowing to configure language server-specific options.
57: # Maps the language key to the options.
58: # Have a look at the docstring of the constructors of the LS implementations within solidlsp (e.g., for C# or PHP) to see which options are available.
59: # No documentation on options means no options are available.
60: ls_specific_settings: {}
61: 
62: # list of additional workspace folder paths for cross-package reference support (e.g. in monorepos).
63: # Paths can be absolute or relative to the project root.
64: # Each folder is registered as an LSP workspace folder, enabling language servers to discover
65: # symbols and references across package boundaries.
66: # Currently supported for: TypeScript.
67: # Example:
68: #   additional_workspace_folders:
